insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (37, 'Night Tree', 'Bunting, Eve', NULL, 'On a cold Christmas Eve, a family drives out to Luke''s Forest, where they greet their favorite tree like an old friend and decorate it with edible ornaments for the animals of the woods in this "refreshing alternative to the tinsel and sugarplum commercialism of many Christmas offerings" ("Publishers Weekly"). Full color. Copyright © Libri GmbH. All rights reserved.', 'verified', '037_night_tree.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (38, 'Kookaburras Love to Laugh', 'Bunting, Laura', NULL, 'It is no laughing matter when you are the most serious bird in the borough. Kookaburras love to laugh. They laugh when it is sunny, or rainy, or windy. They laugh for no reason at all. When one serious kookaburra decides to flee the jokers, and goes to find a more suitable flock, he finds that perhaps he might just be in the right place after all.', 'verified', '038_kookaburras_love_to_laugh.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (39, 'Mopoke', 'Bunting, Philip', NULL, 'This is a mopoke. Mopoke loves peace and quiet. He is about to find out that you can''t always get what you want. Visually brilliant and hysterically funny, Philip Bunting''s pictures tell a thousand words, with the support of very sparse, very hilarious, text. This is a book destined to become a classic.', 'verified', '039_mopoke.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (40, 'Not Cute.', 'Bunting, Philip', NULL, 'Quokka did not like being cute. Not one bit. The romping, stomping, chomping tale of one stubbornly adorable marsupial.', 'verified', '040_not_cute.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (41, 'Timeless', 'Canby, Kelly', NULL, 'Emit (time spelled backwards) is surrounded by busyness - his parents are too busy to read stories or play games. He tries to catch time, wait for it, buy it, but learns the secret: if you want time, you have to make it. A story about modern busyness, family quality time, and slowing down to appreciate moments.', 'verified', '041_timeless.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (42, 'Crickwing', 'Cannon, Janell', NULL, 'A lonely cockroach named Crickwing has a creative idea that saves the day for the leaf-cutter ants when their fierce forest enemies attack them.', 'verified', '042_crickwing.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (43, 'Verdi', 'Cannon, Janell', NULL, 'A young python does not want to grow slow and boring like the older snakes he sees in the tropical jungle where he lives.', 'verified', '043_verdi.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (44, 'The Very Hungry Caterpillar', 'Carle, Eric', NULL, 'Eric Carle''s classic The Very Hungry Caterpillar, with an enclosed CD.This is a book and CD pack of the best selling picture book, The Very Hungry Caterpillar. There is a straight reading of the story first with intro and exit music and then a reading that includes a ''ping'' to turn the page.Eric Carle is an internationally bestselling and award-winning author and illustrator of books for very young children. Eric lives in Massachusetts with his wife, Barbara. The Carles opened The Eric Carle Museum of Picture Book Art in Massachusetts in 2002.Don''t miss all the other Very Hungry Caterpillar and Eric Carle books:The Very Hungry Caterpillar; Eric Carle''s Very Special Baby Book; Polar Bear, Polar Bear, What do You Hear?; The Very busy Spider; The Very Quiet Cricket; The Artist Who Painted a Blue Horse; 1, 2, 3 to the Zoo; Baby Bear, Baby Bear, What do you See?; The Very Hungry Caterpillar Pop-Up Book; Polar Bear, Polar Bear, What Do You Hear?; The Very Hungry Caterpillar''s Buggy Book; Brown Bear, Brown Bear, What Do You See?; The Bad-Tempered Ladbybird; The Very Hungry Caterpillar: Little Learning Library; The Very Hungry Caterpillar: Touch and Feel Playbook; My Very First Book of Words; The Very Hungry Caterpillar Book and Toy; Little Cloud; Today is Monday; My Very First Book of Shapes; The Very Hungry Caterpillar''s Sound Book; The Very Hungry Caterpillar; From Head to Toe; The Very Hungry Caterpillar Big Board Book; Draw Me a Star; Mister Seahorse; Do You want to be My Friend?; The Tiny Seed', 'verified', '044_the_very_hungry_caterpillar.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (45, 'The Very Busy Spider', 'Carle, Eric', NULL, 'A spider, blown by the wind to a fence post near a farm yard, begins to build her web and cannot be distracted from the task at hand--not by the horse, cow, sheep, goat, or dog. But when the rooster asks if she wants to catch a pesky fly, the busy spider is able to catch it in her web immediately!', 'verified', '045_the_very_busy_spider.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (46, 'Brown Bear, Brown Bear, What Do You See?', 'Carle, Eric', NULL, 'Eric Carle''s familiar illustrations of brown bear, red bird, yellow duck and the other endearing animals from his classic creation parade across the pages of this great interactive board book. As each page is turned, a new animal and its colour are introduced, accompanied by Bill Martin''s singsong, rhyming questionand- response text to read aloud or listen to. There are sliding doors throughout the book, which children will just love to open, so they can discover what the next animal in this engaging story will be.', 'verified', '046_brown_bear_brown_bear_what_do_you_see.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (47, 'The Elephant', 'Carnavas, Peter', NULL, 'Olive''s father has a sadness so big that she imagines it as a large grey elephant following him around. With the help of her cheery grandfather and her best friend, Arthur, Olive sets out to chase away her father''s elephant.', 'verified', '047_the_elephant.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (48, 'Oliver and George', 'Carnavas, Peter', NULL, 'Oliver (a boy) wants to play but George (a bear) is too busy reading. Oliver tries everything to get George''s attention. A humorous picture book about what happens when a boy bothers a bear too many times.', 'verified', '048_oliver_and_george.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (49, 'A Quiet Girl', 'Carnavas, Peter', 'Peter Carnavas', 'Now in paperback, the award-winning picture book about embracing quiet in a noisy world. Mary knows how to savor the small things. Wonder is everywhere: in the rustle of leaves, in the sigh of a sleeping dog, in the wingbeats of the birds who visit her upcycled feeders. But Mary''s family couldn''t be more different. Amidst the sound of blow-dryers, blenders, lawnmowers, and her brother''s trombone, Mary goes almost unnoticed. It isn''t until her family starts searching the neighborhood for her that they begin to see the world through her eyes. From critically acclaimed author-illustrator Peter Carnavas comes a gentle breeze of a picture book with themes of mindfulness, observation, and being present in nature. A Quiet Girl invites young readers (and the noisy adults in their lives) to appreciate the thousand little pleasures that surround us--if only we would notice them. A closing spread about mindfulness rounds out this validating story for introverts and observers everywhere. "A quiet young girl in a noisy world, Mary shows her loud, busy family that listening allows for more to be heard."--School Library Journal STARRED REVIEW', 'verified', '049_a_quiet_girl.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (50, 'The Great Expedition', 'Carnavas, Peter', NULL, 'On August 20, a group of young explorers were charged with a dangerous mission. They were to travel across wild country to deliver a valuable parcel. The journey would be punishing. It would test the resolve of the brave young explorers. Most of all, it would provide us all with a pair of unlikely heroes to admire and remember for many years to come. This is their story. The Great Expedition is a delightful parody about five children attempting to cross the park to deliver cake to Grandma.', 'verified', '050_the_great_expedition.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (51, 'Jessica''s Box', 'Carnavas, Peter', 'Peter Carnavas', 'Jessica''s Box is the story of a young girl starting school. Each day, she takes something special in her cardboard box in the hope of winning friends. Day after day, it doesn''t work, until Jessica discovers the one thing she must take, and it''s not quite what she expected.', 'verified', '051_jessicas_box.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (52, 'The Boy on the Page', 'Carnavas, Peter', NULL, 'A small boy lands on the page and, quite by accident, discovers the joy and wonder of life.', 'verified', '052_the_boy_on_the_page.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (53, 'Wombat', 'Cheng, Christopher', NULL, 'Learn all about the Australian “bulldozer of the bush” in a fascinating introduction to the wombat. Wombats may look soft and cuddly, but they are determined and tough, with sharp teeth that never stop growing, limbs that they use to shovel dirt like bulldozers, and bony bottoms they use to defend their burrows. They can live for years without drinking water, getting all of their moisture from the plants they eat—and they deposit their cube-shaped poop on rocks or stumps as a warning to other wombats. Follow one of these powerful marsupials through a suspenseful day in Christopher Cheng’s engaging narration, paired with endearing illustrations by Liz Duthie and interspersed with intriguing facts. An endnote provides additional information about wombats for readers curious to learn more.', 'verified', '053_wombat.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (54, 'The Great Kapok Tree', 'Cherry, Lynne', NULL, 'The many different animals that live in a great Kapok tree in the Brazilian rainforest try to convince a man with an ax of the importance of not cutting down their home.', 'verified', '054_the_great_kapok_tree.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (55, 'A Trip to the Hospital', 'Chiu, Freeda', NULL, 'A children''s book that explores all the amazing things that happen inside a children''s hospital and gives thanks to the many hardworking people that help keep us safe and well. SHORT-LISTED: 2022 CBCA Book of the Year, Award for New Illustrator Going to hospital might seem scary or worrying - you might be hurt, you might feel sick or maybe you just have to visit a friend. But don''t be worried! Hospitals are amazing places filled with clever people all doing incredible things, including making you feel better. Follow Momo, Rani and Henry on three very different adventures inside a busy children''s hospital. A picture book that shows children all the interesting things that happen inside a hospital, helping them feel safe and secure, and ready for their first visit. ''A friendly introduction to the idea of hospitals and what might happen in them ... A good book for parents to use as a starting point for talking to kids about hospitals.'' Books+Publishing ''A timely and important book.'' Reading Time', 'verified', '055_a_trip_to_the_hospital.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (56, 'Amira''s Suitcase', 'Conley, Vikki', NULL, 'It begins with a tiny seed growing inside a suitcase. With Amira''s care, the tiny seed starts to sprout. Find out what happens when kindness flourishes...
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (57, 'Where the Lyrebird Lives', 'Conley, Vikki', NULL, 'Age range 3 to 6 High in the mountains through the sleepy clouds. Deep in the forest past the chiming birds. Will we see the lyrebird? I don''t know. Tip-toe, tip-toe. The beauty of the Australian rainforest and the magic of family-time come together in this lyrical and delightful story of intergenerational connection, habitat and adventure.', 'verified', '057_where_the_lyrebird_lives.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (58, 'Wolf in the Snow', 'Cordell, Matthew', 'Matthew Cordell', 'When a wolf cub and little girl are lost in a snowstorm they must find their way home.', 'verified', '058_wolf_in_the_snow.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (59, 'Amazing Animal Journeys', 'Cossins, Jennifer', NULL, 'Did you know that Arctic terns have the longest migration of all birds, flying from the Arctic to Antarctica and back each year? Or that the wildebeest migration in east Africa is so vast it can be seen from outer space? Come along on these amazing animal journeys! Perfect for readers aged 7+ who delight in learning about the animal kingdom and the world around them. Praise for AMAZING ANIMAL JOURNEYS ''Stunningly illustrated'' SUNDAY TELEGRAPH ''Highly recommended'' READPLUS ''A terrific addition to the Jennifer Cossins shelf . . . This book makes you constantly feel in awe'' GOOD READING MAGAZINE ''Perfect for young readers wanting to learn more about our amazing animal kingdom'' WEST AUSTRALIAN ''A revelation . . . inviting young readers and their adults to delve and consider the results of human activity on the natural world . . . It''s a beautiful looking book too with every page a work of art'' LIVING ARTS CANBERRA Praise for Jennifer Cossins ''For those interested in words, and especially those with children who have an enquiring mind and a thirst for knowledge, any book by Tasmanian author and artist Jennifer Cossins is ideal'' KIDS'' BOOK REVIEW ''We love . . . Jennifer Cossins'' The Baby Animal Book'' WEEKEND AUSTRALIAN', 'verified', '059_amazing_animal_journeys.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (60, 'The Watertower', 'Crew, Gary', NULL, 'Nobody in Preston could remember when the watertower was built, or or who had built it, but there it stood on Shooters Hill - its iron legs rusted, its egg-shaped tank warped and leaking - casting a long shadow across the valley, across Preston itself.', 'verified', '060_the_watertower.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (64, 'Shortcut', 'Crews, Donald', NULL, 'From Donald Crews, the Caldecott Honor artist and award-winning creator of Bigmama''s, Freight Train, and many other classic picture books for young children, comes "a superb example of the picture book as theater; a suspense thriller for younger audiences" (Horn Book starred review).
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (65, 'Click, Clack, Moo Cows That Type', 'Cronin, Doreen', 'Betsy Lewin', 'The quirky, hilarious farmyard tale that started it all from New York Times bestselling duo of Doreen Cronin and Betsy Lewin! Now the inspiration for a new Christmas special, CLICK, CLACK, MOO: Christmas on the Farm.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (66, 'Diary of a Worm', 'Cronin, Doreen', 'Harry Bliss', 'This hilarious picture book from the bestselling, acclaimed author-illustrator team of Doreen Cronin and Harry Bliss tells the adventures of a worm through his daily diary entries.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (67, 'Wild Australian Life', 'Cronin, Leonard', NULL, 'A stunning new exploration of Australian animals from the creator of the bestselling Australian Animal Atlas.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (68, 'When I Was Little: A Four Year Old''s Memoir of her Youth', 'Curtis, Jamie Lee', 'Laura Cornell', 'Jamie Lee Curtis and Laura Cornell perfectly capture a little girl''s simple, joyous celebration of herself, as she looks back on her childhood from the lofty height of four and a half years.
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (69, 'Charlie and the Chocolate Factory', 'Dahl, Roald', 'Quentin Blake', 'Willy Wonka''s famous chocolate factory is opening at last! But only five lucky children will be allowed inside. And the winners are: Augustus Gloop, an enormously fat boy whose hobby is eating; Veruca Salt, a spoiled-rotten brat whose parents are wrapped around her little finger; Violet Beauregarde, a dim-witted gum-chewer with the fastest jaws around; Mike Teavee, a toy pistol-toting gangster-in-training who is obsessed with television; and Charlie Bucket, Our Hero, a boy who is honest and kind, brave and true, and good and ready for the wildest time of his life!', 'verified', '069_charlie_and_the_chocolate_factory.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (71, 'The Twits', 'Dahl, Roald', 'Quentin Blake', 'The misadventures of two terrible old people who enjoy playing nasty tricks and are finally outwitted by a family of monkeys.', 'verified', '071_the_twits.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (72, 'One Tiny Turtle', 'Davies, Nicola', NULL, 'The story of a tiny sea turtle who swims out to sea, then returns after a few years to the beach where she was born to lay her eggs before returning to the sea. Includes many facts about sea turtles.', 'verified', '072_one_tiny_turtle.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (73, 'Every Child a Song', 'Davies, Nicola', NULL, 'An international look at children''s rights, exploring global issues faced by children, encouraging compassion and empathy. Illustrated by award-winning illustrator Marc Martin. When you were born, a song began… So begins this lyrical and unique nonfiction picture book by award-winning children’s author Nicola Davies. With tenderness and heart, Nicola introduces young readers to the universal rights that every child is entitled to under the United Nations Convention on the Rights of the Child. Using the metaphor of song, the book opens with the arrival of a newborn and its unique “song,” then pans out to explore all the essential things that every song needs to thrive—love, protection, a home, a name, the chance to explore and learn. In the latter half of the book, the issues of child labor, exploitation and war are sensitively introduced to emphasize that we all must play our part in championing children’s rights and offering support to those who need it most. With deeply moving watercolor illustrations by award-winning artist Marc Martin, this is a book that encourages children and adults alike to speak up for young people all around the world, and to treat one another with compassion and kindness. Crocodile Books, an imprint of Interlink Publishing, will donate 5% of the selling price of each book sold to The Young Center for Immigrant Children’s Rights, a human rights organization that advocates for the rights and best interests of immigrant children. About The Young Center for Immigrant Children’s Rights: The Young Center for Immigrant Children’s Rights is a human rights organization that advocates for the rights and best interests of immigrant children. It protects and advances the rights and best interests of immigrant children according to the Convention on the Rights of the Child and state and federal law. It is a champion for the rights and best interests of unaccompanied immigrant children, making sure that wherever they land, whether here in the U.S. or in their home country, they are safe.', 'verified', '073_every_child_a_song.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (74, 'Big Blue Whale', 'Davies, Nicola', NULL, 'With conversational text and pen-and-ink illustrations, Davies and Maland examine the largest mammal on Earth, detailing the physical characteristics, habits, and habitats of the blue whale.', 'verified', '074_big_blue_whale.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (75, 'The Day the Crayons Quit', 'Daywalt, Drew', 'Oliver Jeffers', 'The hilarious, colorful #1 New York Times bestselling phenomenon that every kid wants! Gift a copy to someone you love today. Poor Duncan just wants to color. But when he opens his box of crayons, he finds only letters, all saying the same thing: His crayons have had enough! They quit! Blue crayon needs a break from coloring all those bodies of water. Black crayon wants to be used for more than just outlining. And Orange and Yellow are no longer speaking—each believes he is the true color of the sun. What can Duncan possibly do to appease all of the crayons and get them back to doing what they do best? With giggle-inducing text from Drew Daywalt and bold and bright illustrations from Oliver Jeffers, The Day the Crayons Quit is the perfect gift for new parents, baby showers, back-to-school, or any time of year! Perfect for fans of Don''t Let the Pigeon Drive the Bus by Mo Willems and The True Story of the Three Little Pigs by Jon Sciezka and Lane Smith. Praise for The Day the Crayons Quit: Amazon’s 2013 Best Picture Book of the Year A Barnes & Noble Best Book of 2013 Goodreads’ 2013 Best Picture Book of the Year Winner of the E.B. White Read-Aloud Award * “Hilarious . . . Move over, Click, Clack, Moo; we’ve got a new contender for the most successful picture-book strike.” –BCCB, starred review “Jeffers . . . elevates crayon drawing to remarkable heights.” –Booklist “Fresh and funny.” –The Wall Street Journal "This book will have children asking to have it read again and again.” –Library Media Connection * “This colorful title should make for an uproarious storytime.” –School Library Journal, starred review * “These memorable personalities will leave readers glancing apprehensively at their own crayon boxes.” –Publishers Weekly, starred review “Utterly original.” –San Francisco Chronicle', 'verified', '075_the_day_the_crayons_quit.jpg');
